const enterpriseSections=[[1, 8, "Business profile"], [9, 16, "Markets & ownership"], [17, 24, "Registration & records"], [25, 35, "Workers & inclusion"], [36, 45, "Inputs & capacity"], [46, 60, "Equipment & infrastructure"], [61, 73, "Finance & profitability"], [74, 83, "Risk & market continuity"], [84, 92, "Livelihood links & expansion"]];
window.FORMS.ENT=[...common,demographics,...enterpriseSections.map(([start,end,title])=>({title,fields:window.ENTERPRISE_SOURCE.filter(f=>f.number>=start&&f.number<=end).flatMap(f=>[f,...(f.options.includes("Other")?[q(f.id+"Other","Other — please specify","text",[],{show:[f.id,"Other"]})]:[])])})),home,processing,trade];
window.FORM_NAMES.ENT="Enterprise survey";
// Adaptations remain explicit; source wording/options are retained above for audit.
for(const s of FORMS.ENT)for(const f of s.fields){
 if(f.id==='ent8')f.showIn=['ent7',['Active seasonally','Temporarily closed']];
 if(f.id==='ent19')f.showIn=['ent17',['No, not registered','Registration in progress','Other']];
 if(f.id==='ent71')f.show=['ent70','Yes'];
 if(f.id==='ent11')f.label='Who are the main customers?';
 if(f.id==='ent6'){f.type='select';f.cardinalityAdapted=true}
 if(f.id==='ent5')f.max=new Date().getFullYear();
}
const extra=(id,label,type='number',options=[],props={})=>q(id,label,type,options,{required:false,min:type==='number'?0:undefined,...props,proposedAddition:true});
FORMS.ENT.splice(FORMS.ENT.length-3,0,{title:'Measurement details',note:'Proposed additions from the leadership framework. Keep source bands above. Exact values are optional, self-reported and are not financial verification. Worker categories can overlap; use the separate unique-worker count for totals.',fields:[
 extra('enterpriseRef','Existing enterprise ID, if known','text'),
 extra('financialMonth','Financial reporting month','month'),
 extra('revenueExact','Exact monthly revenue (₦)'),extra('costExact','Exact monthly operating cost (₦)'),extra('profitExact','Exact monthly net profit (₦)','number',[],{min:undefined}),
 extra('peakExact','Exact peak-month revenue (₦)'),extra('leanExact','Exact lean-month revenue (₦)'),
 extra('totalWorkers','Unique people working here — current headcount','number',[],{integer:true}),
 ...['Permanent employees','Seasonal workers','Casual/daily wage workers','Paid family workers','Unpaid family workers','Apprentices/trainees','Self-employed owner'].map((x,i)=>extra('workerCount'+i,x+' — count (categories may overlap)','number',[],{integer:true})),
 extra('measurementCommodity','Commodity for this capacity measurement','select',[...crops,'Bread wheat','Garlic','Services / non-crop']),
 extra('capacityUnit','Physical output unit','select',['kg','tonnes','litres','items','service transactions','Other']),
 extra('installedMonthlyCapacity','Installed maximum capacity per month — same unit as output'),extra('monthlyOutput','Actual output per month — same unit as capacity'),
 extra('inputQuantity','Actual input quantity required'),extra('inputUnit','Input quantity unit','select',['kg','tonnes','litres','items','Other']),extra('inputPeriod','Input reporting period','select',['Daily','Weekly','Monthly','Seasonally','Per order']),
 extra('plannedSupportCost','Proposed intervention cost (₦)'),extra('expectedExtraJobs','Proposed additional unique jobs — estimate','number',[],{integer:true}),extra('implementationMonths','Proposed implementation time (months)','number',[],{integer:true}),extra('measurementNotes','Measurement assumptions / evidence notes','textarea')
]});
// The enterprise PDF's repeated trade section stops at major buyers.
FORMS.ENT[FORMS.ENT.length-1]={title:'Trade & markets',fields:trade.fields.filter(f=>['trade','market','tradedCrops','tradeQty','rawPrice','processedPrice','processChallenges','buyers'].includes(f.id))};
window.CATALOG.ENT=ENTERPRISE_SOURCE.map(f=>f.number+'. '+f.sourceLabel);

for(const s of FORMS.ENT)for(const f of s.fields){if(f.id==='ent5')f.integer=true;if(f.id.endsWith('Other')){const parent=FORMS.ENT.flatMap(s=>s.fields).find(x=>x.id===f.id.slice(0,-5));if(parent?.showIn)f.showIn=parent.showIn;if(parent?.show)f.showIn=[parent.show[0],[parent.show[1]]];}}
const enterpriseExclusive={ent21:['No records maintained'],ent22:['No formal record-keeping'],ent72:['No major challenges'],ent74:['None'],ent76:['No formal risk management strategy'],ent77:['No insurance',"Don't know"],ent86:['No significant impact.'],ent87:['No significant infrastructure challenges'],ent88:['No significant environmental risks'],ent89:['No significant occupational risks'],ent91:['No expansion plans currently']};
for(const s of FORMS.ENT)for(const f of s.fields)if(enterpriseExclusive[f.id])f.exclusiveOptions=enterpriseExclusive[f.id];
// The enterprise PDF's repeated commodity grids also include these two rows.
for(const section of FORMS.ENT)if(['Processing','Trade & markets'].includes(section.title))section.fields=section.fields.map(f=>['processedCrops','tradedCrops'].includes(f.id)?{...f,options:[...new Set([...f.options,'Bread wheat','Garlic'])]}:f);
